public class ProblemB {

    private void processInput(char[] inputChars, PrintWriter outputWriter) {
        int currentIndex = 0;
        int maxSequence = 0;
        int totalPairs = 0;
        boolean inParentheses = false;
        while (currentIndex < inputChars.length) {
            if (inputChars[currentIndex] == '(') {
                inParentheses = true;
            } else if (inputChars[currentIndex] == ')') {
                inParentheses = false;
            } else if (Character.isLetter(inputChars[currentIndex]))
                currentIndex--;
            if (inParentheses) {
                while (++currentIndex != inputChars.length && inputChars[currentIndex] != ')' && !Character.isLetter(inputChars[currentIndex]));
                if (currentIndex == inputChars.length || !Character.isLetter(inputChars[currentIndex])) {
                    continue;
                }
                while (Character.isLetter(inputChars[++currentIndex]));
                totalPairs++;
            } else {
                while (++currentIndex != inputChars.length && inputChars[currentIndex] != '(' && !Character.isLetter(inputChars[currentIndex]));
                if (currentIndex == inputChars.length || !Character.isLetter(inputChars[currentIndex])) {
                    continue;
                }
                int startIdx = currentIndex;
                while (++currentIndex != inputChars.length && Character.isLetter(inputChars[currentIndex]));
                maxSequence = Math.max(maxSequence, currentIndex - startIdx);
            }
        }
        outputWriter.println(maxSequence + " " + totalPairs);
    }

    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            br.readLine();
            new ProblemB().processInput(br.readLine().toCharArray(), pw);
        }
    }
}
