#include <iostream>
#include <string>
#include <algorithm>

void processInput(const std::string& inputStr) {
    int currentIndex = 0;
    int maxSequence = 0;
    int totalPairs = 0;
    bool inParentheses = false;
    const int length = inputStr.length();

    while (currentIndex < length) {
        if (inputStr[currentIndex] == '(') {
            inParentheses = true;
        } else if (inputStr[currentIndex] == ')') {
            inParentheses = false;
        } else if (isalpha(inputStr[currentIndex])) {
            currentIndex--;
        }
        if (inParentheses) {
            while (++currentIndex != length && inputStr[currentIndex] != ')' && !isalpha(inputStr[currentIndex]));
            if (currentIndex == length || !isalpha(inputStr[currentIndex])) {
                continue;
            }
            while (isalpha(inputStr[++currentIndex]));
            totalPairs++;
        } else {
            while (++currentIndex != length && inputStr[currentIndex] != '(' && !isalpha(inputStr[currentIndex]));
            if (currentIndex == length || !isalpha(inputStr[currentIndex])) {
                continue;
            }
            int startIdx = currentIndex;
            while (++currentIndex != length && isalpha(inputStr[currentIndex]));
            maxSequence = std::max(maxSequence, currentIndex - startIdx);
        }
    }
    std::cout << maxSequence << " " << totalPairs << std::endl;
}

int main() {
    std::string dummyLine;
    std::getline(std::cin, dummyLine); // Read and ignore the first line
    std::string inputLine;
    std::getline(std::cin, inputLine);
    processInput(inputLine);
    return 0;
}

